local a={}local b={}aeslua.gf=b;a.n=0x100;a.ord=0xff;a.irrPolynom=0x11b;a.exp={}a.log={}function b.add(c,d)return bit.bxor(c,d)end;function b.sub(c,d)return bit.bxor(c,d)end;function b.invert(e)if(e==1)then return 1 end;local f=a.ord-a.log[e]return a.exp[f]end;function b.mul(c,d)if(c==0 or d==0)then return 0 end;local f=a.log[c]+a.log[d]if(f>=a.ord)then f=f-a.ord end;return a.exp[f]end;function b.div(c,d)if(c==0)then return 0 end;local f=a.log[c]-a.log[d]if(f<0)then f=f+a.ord end;return a.exp[f]end;function a.initMulTable()local g=1;for h=0,a.ord-1 do a.exp[h]=g;a.log[g]=h;g=bit.bxor(bit.lshift(g,1),g)if g>a.ord then g=b.sub(g,a.irrPolynom)end end end;a.initMulTable()return b